public class Main {
    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int force = fs.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        int[] queue = new int[n * n];
        int head = 0, tail = 0;

        if (grid[0][0] - '0' <= force) {
            grid[0][0] = '*';
            queue[tail++] = 0;

            while (head < tail) {
                int pos = queue[head++];
                int r = pos / n;
                int c = pos % n;

                if (r > 0 && grid[r - 1][c] != '*' && grid[r - 1][c] - '0' <= force) {
                    grid[r - 1][c] = '*';
                    queue[tail++] = pos - n;
                }
                if (r + 1 < n && grid[r + 1][c] != '*' && grid[r + 1][c] - '0' <= force) {
                    grid[r + 1][c] = '*';
                    queue[tail++] = pos + n;
                }
                if (c > 0 && grid[r][c - 1] != '*' && grid[r][c - 1] - '0' <= force) {
                    grid[r][c - 1] = '*';
                    queue[tail++] = pos - 1;
                }
                if (c + 1 < n && grid[r][c + 1] != '*' && grid[r][c + 1] - '0' <= force) {
                    grid[r][c + 1] = '*';
                    queue[tail++] = pos + 1;
                }
            }
        }

        StringBuilder out = new StringBuilder(n * (n + 1));
        for (int i = 0; i < n; i++) {
            out.append(grid[i]).append('\n');
        }
        System.out.print(out);
    }
}
